class RoomBuffer {
  constructor(limit) {
    this.queue = [];
    this.limit = limit;
    this.nextSequence = 0;
  }

  push(message) {
    if (this.queue.length >= this.limit) return false;
    this.queue.push(message);
    return true;
  }
}
